struct BookTone { let background: Color; let foreground: Color }

extension BookFamily {
    var tone: BookTone {
        switch self {
        case .wiki: return BookTone(background: Color(light: 0xE9DFC8, dark: 0x2A3A2F), foreground: Color(light: 0x1F3D2F, dark: 0xE9DFC8))
        case .maps: return BookTone(background: Color(light: 0xDCE6D3, dark: 0x22392B), foreground: Color(light: 0x2F5642, dark: 0xB5CFA2))
        case .aid: return BookTone(background: Color(light: 0xF6D8CE, dark: 0x3B211B), foreground: Color(light: 0xB4321F, dark: 0xF0A08F))
        case .books: return BookTone(background: Color(light: 0xEFDDBF, dark: 0x33291A), foreground: Color(light: 0x7A4B12, dark: 0xE3C08E))
        case .games: return BookTone(background: Color(light: 0xFBDCC8, dark: 0x3A2416), foreground: Color(light: 0xA33F05, dark: 0xFFB98C))
